+  if (/\bweekdays?\b|\bmon(?:day)?s?\s*(?:-|–|to|through)\s*fri(?:day)?\b|\bbusiness days?\b|\bworkdays?\b/.test(lower)) weekdays = [1, 2, 3, 4, 5];
