+      skip({ kind: "skill", name: label, reason: `a bot holds at most ${AGENT_MAX_SKILLS} skills`, ...(skill.body ? { original: skill.body } : {}) });
+      continue;
+    }
+    const entry = skillEntry(skill, uniqueSlug(skill.name, `skill-${index + 1}`, skillNames));
