+    instructions,
+    ...(card.creator ? { creator: card.creator } : {}),
+    ...(card.color ? { color: card.color } : {}),
+    skills: [],
+    routines: [],
+    plugins: [],
+    memories: [],
+  }, { sourceUrl: grokShareUrl(card.shareId) }).document;
+}

