+      // SAFETY: this endpoint is owned by the app and returns CursorStatus.
+      void api("/api/team-library/cursor").then((status) => {
+        const next = status as CursorStatus;
+        setCursor(next);
+        if (next.signedIn && loaded.current) void load(loaded.current);
+      }, () => {});
